import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 85 · Christmas tips: make your house smell like Christmas

sc("""Sweetheart, when people walked into my mother's house in December, the first thing they said wasn't, what a pretty tree. It was, oh my goodness, what is that smell? Oranges, cinnamon, pine, and something baking. Today people spend thirty dollars on a candle that smells like chemicals and gives them a headache. My mother did it for about a quarter, and her house smelled like Christmas from the front walk.""",
   "cozy old kitchen Christmas steam stove", "WHAT IS THAT SMELL?")
sc("""So tonight I'm giving you nine old-fashioned ways to make your whole house smell like Christmas, for almost nothing, and without one chemical candle. And stay with me, because number nine is the one my mother did every December morning, and it's the reason the mailman used to stand on our porch a little longer than he needed to.""",
   "simmering pot oranges cinnamon on stove", "NINE OLD TRICKS")

ch("Mother's kitchen")
sc("""In the nineteen fifties, honey, nobody had air fresheners. There were no plug-ins, no fancy candles from the mall. If you wanted your house to smell good, you made it smell good, with what you had in the kitchen and what you found in the woods. And those smells are still the ones that make grown men in their seventies close their eyes and say, that's Christmas.""",
   "1950s kitchen with pine and oranges", "NO AIR FRESHENERS")
sc("""Smell is the strongest memory there is, sweetheart. Scientists say it goes straight to the part of the brain that holds memories and feelings. That's why one sniff of cinnamon can put you right back in your grandmother's kitchen when you were six. If you want your children to remember Christmas at your house, give them a smell to remember. In a minute I'll tell you which smell lasts the longest.""",
   "child smelling cookies grandmother kitchen", "THE STRONGEST MEMORY")

ch("1. The simmer pot")
sc("""Number one. The simmer pot. Fill a small pot two-thirds with water. Add the peels of two oranges, three cinnamon sticks, a tablespoon of whole cloves, and a few slices of fresh ginger or a splash of vanilla. Bring it to a boil, then turn it down to the lowest heat and let it barely steam all afternoon. The whole house smells like Christmas in fifteen minutes.""",
   "pot of orange peel cinnamon cloves simmering", "THE SIMMER POT")
sc("""Just keep an eye on the water, honey. Add a cup every hour so it never boils dry, because that's how you scorch a pot. And you can use it for three days. Keep it in the icebox overnight and put it back on the stove in the morning. When it stops smelling, throw in a fresh handful of cranberries and a sprig of pine, and it comes right back to life.""",
   "adding water and cranberries to pot", "ADD WATER EVERY HOUR")

sc("""And here's a Christmas gift idea from the simmer pot. Put the dry ingredients in a pretty mason jar. Dried orange slices, three cinnamon sticks, a spoonful of cloves, a few star anise, and a little sprig of rosemary. Tie on a tag that says, add water and simmer. I give them to every neighbor, and they cost about a dollar fifty a jar. People love them more than candles.""",
   "mason jar simmer pot gift with tag", "A JAR FOR THE NEIGHBORS")
ch("2. Clove oranges")
sc("""Number two. Clove oranges, or pomanders. My mother made these with Danny and me every December. Take an orange and poke whole cloves into the skin, all over, in rows or swirls. Use a toothpick to make the holes first, or your thumbs will be sore. Roll it in a little cinnamon, and tie a ribbon around it. They smell wonderful for weeks, and as they dry, the smell gets stronger.""",
   "orange studded with cloves ribbon", "CLOVE ORANGES")
sc("""Hang them from the curtain rods, put a bowl of them on the table, or tuck them in a closet. The old ones from the year before, all dried and hard, went in our dresser drawers to make the sweaters smell good. Grandma Pearl said in her day, people carried them in their pockets to church, to cover up the smell of the farmers who'd just finished milking.""",
   "bowl of dried pomanders on table", "IN THE DRESSER DRAWERS")

ch("3. Real greenery")
sc("""Number three. Real greenery. A fake tree looks fine, but it smells like a plastic box from the attic. Even if you keep your fake tree, tuck real branches into it. Most tree lots will give you their trimmed-off branches for free if you ask. Fir, cedar, pine. Put some on the mantel, over the doorways, in a jug on the kitchen table. Cedar smells the strongest and lasts the longest.""",
   "fresh cedar and fir branches in jug", "ASK FOR THE FREE BRANCHES")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. And here's a trick for when the branches start to fade. Mist them with a spray bottle of water every couple of days. It brings the smell right back out. And if you have a fireplace, toss a little handful of dry pine needles into the fire. It crackles and smells like the woods.""",
   "spray bottle misting pine branches", "MIST THEM")

sc("""And remember I promised to tell you which smell lasts the longest? It's cedar, sweetheart. A few cedar branches will smell good for three weeks, long after the pine and fir have faded. Grandma Pearl lined her whole front porch railing with cedar every December, and in January she put the dried branches in the closets to keep the moths away. Nothing went to waste in her house.""",
   "cedar branches on porch railing", "CEDAR LASTS LONGEST")
ch("4. Cinnamon pinecones")
sc("""Number four. Cinnamon pinecones. Gather pinecones from outside, dry ones, and bake them on a cookie sheet at two hundred degrees for half an hour to get rid of any bugs. Then put them in a paper bag with a few drops of cinnamon oil, or sprinkle them with ground cinnamon and cloves. Close the bag for a week. Then put them in a basket by the front door. Every guest gets a sniff.""",
   "basket of cinnamon pinecones by door", "CINNAMON PINECONES")

ch("5. Something baking")
sc("""So far, a simmer pot, clove oranges, real greenery, and cinnamon pinecones. Number five. Something baking. Nothing in the world makes a house smell like home more than bread or cookies in the oven. But you don't have to bake a whole batch. Keep a roll of cookie dough in the freezer and bake six cookies right before company comes. Or put a pan of cinnamon and sugar in a warm oven for ten minutes.""",
   "cookies baking in oven warm kitchen", "SOMETHING BAKING")

sc("""My mother kept a jar of cookie dough in the icebox all December, honey, for exactly this reason. When the doorbell rang and it was the minister, or the neighbors, she'd have a tray of warm cookies on the table in twelve minutes. And the whole house would smell like she'd been baking all day. People thought she was the best housekeeper on Elm Street. She just knew the trick.""",
   "tray of warm cookies on kitchen table", "TWELVE MINUTES")
ch("6. The light bulb trick")
sc("""Number six. The light bulb trick, from my mother's sister. In her day, people put a drop of vanilla on a cold light bulb. Don't do that today, honey. Instead, put a few drops of vanilla or cinnamon oil on a cotton ball and tuck it into the lampshade's base, near the warm lamp but never touching the bulb. The gentle warmth carries the smell through the whole room.""",
   "table lamp glowing warm living room", "THE LIGHT BULB TRICK")

ch("7. Coffee and cocoa")
sc("""Number seven. A pot of coffee with a cinnamon stick in the grounds. Before you brew, put a whole cinnamon stick, or half a teaspoon of ground cinnamon, right in the coffee filter with the grounds. The kitchen smells like a bakery, and the coffee tastes like Christmas morning. My father drank it that way from Thanksgiving to New Year's and called it his holiday coffee.""",
   "cinnamon stick in coffee filter", "HOLIDAY COFFEE")

ch("8. The clean smell")
sc("""Number eight. Start with a clean smell. All the cinnamon in the world won't cover up a stale house. Open the windows for ten minutes in the morning, even in the cold, to let fresh air through. Sprinkle baking soda on the rugs, wait twenty minutes, and vacuum it up. Wipe the kitchen counters with a little white vinegar and a few drops of orange oil. Then add your Christmas smells on top.""",
   "opening window in winter fresh air", "START CLEAN")

ch("9. Mother's morning")
sc("""And number nine, the one I promised you. Every December morning, before anybody else was up, my mother put orange peels and cinnamon on top of the warm stove, right on the metal, and let them toast slowly while she made breakfast. Today, honey, put them in a dry cast iron pan on the lowest heat for five minutes. The smell of toasted orange peel goes through every room in the house.""",
   "orange peels toasting in cast iron pan", "TOASTED ORANGE PEEL")
sc("""The mailman, Mr. Bowers, used to stand on our front porch with our mail in his hand, just breathing. My mother would open the door and say, would you like a cup of coffee, Mr. Bowers? And he always said yes. Twenty-two years he delivered our mail, and every Christmas, he got a cup of holiday coffee on our porch. He came to her funeral, honey. He told that story.""",
   "mailman on snowy porch with coffee cup", "THE MAILMAN STAYED")

ch("Grandma's house")
sc("""So one more time. A simmer pot on the stove. Clove oranges. Real greenery, misted. Cinnamon pinecones by the door. Something baking. A drop of vanilla near a lamp. Cinnamon in the coffee. A clean house first. And toasted orange peel every morning. That's how my mother's house smelled, and if you close your eyes, I'll bet you can smell it too.""",
   "warm Christmas home cozy living room", "CLOSE YOUR EYES")
sc("""Tell me in the comments, sweetheart. What smell takes you straight back to Christmas as a child? I'd love to know. The whole playlist of Grandma's Christmas tips is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "grandmother kitchen evening Christmas", "WHAT'S YOUR SMELL?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma85", "9 Old Tricks to Make Your House SMELL Like Christmas (Almost Free)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Pomanders (clove-studded oranges) have been used as natural fragrance since medieval times.",
      "Smell and memory: the olfactory system connects directly to brain areas involved in emotion and memory (amygdala, hippocampus)."],
     "christmas with tips", minutes=(10, 14.5), voice="en_US-lessac-high")
